<script setup lang="ts">
import { computed, ref } from 'vue'
import PageHeading from '@/components/PageHeading.vue'
import AppIcon from '@/components/AppIcon.vue'
import DigestPreview from '@/components/DigestPreview.vue'
import { workspace, save } from '@/lib/workspace'
import { dateLabel, describeError, localDate } from '@/lib/domain'
import type { Attention } from '@/lib/types'
const preview = ref(false), busy = ref(''), error = ref('')
const date = computed(() => localDate(new Date(), workspace.data?.settings.timezone || 'UTC'))
const groups = [{kind:'task',title:'Task follow-ups',hint:'Keep the conversation moving'},{kind:'project',title:'Project deadlines',hint:'Three-day warning window'},{kind:'invoice',title:'Overdue invoices',hint:'Follow up on unpaid work'}]
async function resolve(item: Attention) {
  busy.value = item.id; error.value = ''
  try {
    if (item.kind === 'task') { const record = workspace.data!.tasks.find(t => t.id === item.id)!; await save('task', { ...record, completed: true }, record) }
    if (item.kind === 'invoice') { const record = workspace.data!.invoices.find(i => i.id === item.id)!; await save('invoice', { ...record, paid: true }, record) }
  } catch (e) { error.value = describeError(e) } finally { busy.value = '' }
}
</script>
<template><PageHeading title="Today" :subtitle="workspace.attention.length ? workspace.attention.length + ' items need your attention. One place to keep work moving.' : 'A clear view of what needs your attention.'"><button class="quiet" @click="preview = true"><AppIcon name="mail" /> Preview digest</button></PageHeading><div class="digest-note"><span class="dot" :class="{on:workspace.data?.settings.email_enabled}" /><span>{{ workspace.data?.settings.email_enabled ? 'Email preference enabled' : 'Daily email is off' }} · {{ workspace.data?.settings.timezone || 'Timezone not confirmed' }}</span><RouterLink to="/settings">Reminder settings</RouterLink></div><p v-if="error" class="notice error" role="alert">{{ error }}</p><div v-if="!workspace.data?.settings.timezone" class="empty"><h2>Set your local date.</h2><p>Confirm your timezone so Today uses the right calendar day.</p><RouterLink to="/settings">Confirm timezone</RouterLink></div><template v-else-if="workspace.attention.length"><section v-for="group in groups" :key="group.kind" class="group"><div class="group-head"><h2>{{ group.title }}</h2><span class="count">{{ workspace.attention.filter(i => i.kind === group.kind).length }}</span><span class="hint">{{ group.hint }}</span></div><div v-for="item in workspace.attention.filter(i => i.kind === group.kind)" :key="item.id" class="ledger-row"><div class="row-title"><RouterLink :to="'/projects/' + item.project_id">{{ item.title }}</RouterLink><small v-if="item.project_status !== 'active' && item.kind !== 'project'">{{ item.project_status }} project</small></div><div class="row-context">{{ item.client_name }}<small>{{ item.kind === 'project' ? 'Project deadline' : item.project_name }}</small></div><div class="row-date" :class="{overdue:item.relevant_date < date}">{{ item.relevant_date === date ? 'Today' : dateLabel(item.relevant_date) }}<small>{{ item.kind === 'task' ? 'Follow-up' : item.kind === 'invoice' ? 'Unpaid invoice' : 'Deadline' }}</small></div><div class="row-action"><RouterLink v-if="item.kind === 'project'" :to="'/projects/' + item.project_id">Open project</RouterLink><button v-else class="small" :disabled="busy === item.id" @click="resolve(item)">{{ busy === item.id ? 'Saving…' : item.kind === 'task' ? 'Complete task' : 'Mark paid' }}</button></div></div><p v-if="!workspace.attention.some(i => i.kind === group.kind)" class="section-note">Nothing in this group today.</p><p v-if="group.kind === 'invoice'" class="section-note">Unpaid invoices keep their reminders even when their project is completed.</p></section></template><div v-else-if="!workspace.problem" class="empty"><AppIcon name="check" /><h2>{{ workspace.data?.clients.length ? 'You’re all caught up.' : 'Make room for your first client.' }}</h2><p>{{ workspace.data?.clients.length ? 'No task follow-ups, project deadlines or overdue invoices need attention today.' : 'Add a client, create a project and start tracking the details that matter.' }}</p><RouterLink :to="workspace.data?.clients.length ? '/projects' : '/clients'">{{ workspace.data?.clients.length ? 'Browse projects' : 'Add your first client' }}</RouterLink></div><DigestPreview v-if="preview" @close="preview=false" /></template>
